// === Internshala internship search API ===
// Internshala's listing page (https://internshala.com/internships) is
// powered by an internal JSON endpoint at /hiring/search. Returns
// `internships_meta` (id-keyed object) + `internship_ids` (ordering).
//
// We hit the programming-internship category by default; clone this
// workflow and change the `category=` query for design / marketing /
// data-science / etc.

const BASE = 'https://internshala.com';

function stripHtml(s) {
  if (!s) return null;
  return String(s)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

// Internshala uses several deadline formats ("15 May'26", "2026-05-15",
// unix timestamps, etc). Coerce to YYYY-MM-DD or null.
function normalizeDeadline(value) {
  if (value == null || value === '') return null;
  if (typeof value === 'number') {
    const ms = value < 1e12 ? value * 1000 : value;
    const d = new Date(ms);
    return isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
  }
  const s = String(value).trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  const parsed = new Date(s);
  return isNaN(parsed.getTime()) ? null : parsed.toISOString().slice(0, 10);
}

function formatStipend(stipend) {
  if (!stipend) return null;
  if (stipend.salary && typeof stipend.salary === 'string') {
    return stripHtml(stipend.salary);
  }
  if (stipend.salaryValue1) {
    const cur = stipend.currency === 'INR' || stipend.currency === 'rupee' ? '₹' : '';
    return `${cur}${stipend.salaryValue1} / ${stipend.scale || 'month'}`;
  }
  return null;
}

let data;
try {
  data = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://internshala.com/hiring/search?searchTerm=&filters=&category=programming-internship',
    json: true,
    headers: {
      Accept: 'application/json',
      'User-Agent': 'Mozilla/5.0 (compatible; opportunity-os/1.0)',
    },
  });
} catch (e) {
  throw new Error('Internshala fetch failed: ' + ((e && e.message) || e));
}

const meta = data && data.internships_meta;
if (!meta || typeof meta !== 'object') {
  throw new Error('Internshala returned no internships_meta block');
}
const ids = Array.isArray(data.internship_ids) ? data.internship_ids : Object.keys(meta);
if (ids.length === 0) {
  throw new Error('Internshala returned 0 internship ids');
}

const out = [];
for (const id of ids.slice(0, 25)) {
  const i = meta[id];
  if (!i) continue;
  const rawUrl = i.url || i.apply_url;
  if (!rawUrl) continue;
  const url = String(rawUrl).startsWith('http') ? String(rawUrl) : BASE + String(rawUrl);

  const locArr = Array.isArray(i.location_names) ? i.location_names : [];
  const wfh = i.work_from_home === true || /work from home/i.test(locArr.join(' '));
  const location = wfh ? 'Remote' : (locArr.slice(0, 3).join(', ') || 'India');
  const stipend = formatStipend(i.stipend);
  const title = stripHtml(i.title || i.profile_name || 'Internship');
  const orgName = stripHtml(i.company_name || i.employer_name || 'Internshala');

  const descParts = [];
  if (i.duration) descParts.push(`Duration: ${i.duration}`);
  if (i.start_date) descParts.push(`Starts: ${i.start_date}`);
  if (stipend) descParts.push(`Stipend: ${stipend}`);
  if (i.posted_by_label) descParts.push(stripHtml(i.posted_by_label));

  const opportunity = {
    title: title,
    organization: orgName,
    category: 'internship',
    description: descParts.join(' · ') || null,
    summary: `${title} at ${orgName}${i.duration ? ` (${i.duration})` : ''}.`,
    tags: [],
    deadline: normalizeDeadline(i.application_deadline || i.expires_at),
    eligibility: null,
    location: location,
    compensation: stipend,
    is_remote: wfh,
    apply_url: url,
    difficulty: null,
    estimated_value_score: null,
    extraction_confidence: 0.9,
  };

  out.push({ json: { opportunity, source_url: url } });
}

if (out.length === 0) {
  throw new Error('Internshala produced 0 valid opportunities (likely all rows missing url)');
}
return out;
